alter table public.akp_jobs drop constraint akp_jobs_status_check;
alter table public.akp_jobs add constraint akp_jobs_status_check check(status in ('NOWE','DO_KONTAKTU','DO_UMOWIENIA','UMOWIONE','POMIAR','DO_WYCENY','WYCENA_W_TOKU','OCZEKUJE_NA_KLIENTA','OCZEKUJE_NA_MATERIAL','OCZEKUJE_NA_DOSTAWE','DO_REALIZACJI','W_REALIZACJI','WSTRZYMANE','DO_ODBIORU','DO_ROZLICZENIA','ZAKONCZONE','REKLAMACJA','SERWIS','ANULOWANE','POMIARY','PLANOWANE','REALIZACJA'));
update public.akp_jobs j set status=case when s.source_record->>'STATUS' like 'WYKONANE_ROZLICZONE%' then 'ZAKONCZONE' else s.source_record->>'STATUS' end
from public.akp_job_sources s where s.job_id=j.id and (s.source_record->>'STATUS'=any(array['NOWE','DO_KONTAKTU','DO_UMOWIENIA','UMOWIONE','POMIAR','DO_WYCENY','WYCENA_W_TOKU','OCZEKUJE_NA_KLIENTA','OCZEKUJE_NA_MATERIAL','OCZEKUJE_NA_DOSTAWE','DO_REALIZACJI','W_REALIZACJI','WSTRZYMANE','DO_ODBIORU','DO_ROZLICZENIA','ZAKONCZONE','REKLAMACJA','SERWIS','ANULOWANE','POMIARY','PLANOWANE','REALIZACJA']) or s.source_record->>'STATUS' like 'WYKONANE_ROZLICZONE%') and j.updated_at<=s.synced_at;
